-- Mapeamentos grupo do Keycloak -> perfil + escopo
INSERT INTO ad_group_mappings (ad_group, perfil_id, entidade_id, unidade_id, departamento_id, descricao, created_by)
  SELECT 'NEXUS-ADMINS', p.id, NULL, NULL, NULL, 'Administradores da plataforma (teste)', 'demo-seed' FROM perfis p WHERE p.slug = 'administrador'
  ON CONFLICT DO NOTHING;
INSERT INTO ad_group_mappings (ad_group, perfil_id, entidade_id, unidade_id, departamento_id, descricao, created_by)
  SELECT 'NEXUS-AUDITORES', p.id, NULL, NULL, NULL, 'Auditores (teste)', 'demo-seed' FROM perfis p WHERE p.slug = 'auditor'
  ON CONFLICT DO NOTHING;
INSERT INTO ad_group_mappings (ad_group, perfil_id, entidade_id, unidade_id, departamento_id, descricao, created_by)
  SELECT 'NEXUS-GESTORES-IAM', p.id, NULL, NULL, NULL, 'Gestores de identidade (teste)', 'demo-seed' FROM perfis p WHERE p.slug = 'gestor-iam'
  ON CONFLICT DO NOTHING;
